// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, interpolateColors } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadRubik = makeLoadFont('Rubik');

// Load Google Font at module level
const { fontFamily: rubikFamily } = loadRubik();



export type SosBackgroundProps = Record<string, any>;

const SosBackground: React.FC<SosBackgroundProps> = ({
  backgroundColor = "#020000",
  transparentBackground = false,
  durationInSeconds = 8,
  textColor = "#ff0f0f",
  dimTextColor = "#2d0303",
  fontSize = 110,
  itemWidth = 320,
  rowHeight = 135,
  scrollSpeedMultiplier = 1.0,
  rotationAngle = -18,
  skewAngle = -8,
  glowIntensity = 0.8,
  waveWidth = 600,
  lineOpacity = 0.15,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Ensure robust calculations even with edge cases
  const durationInFrames = Math.max(1, durationInSeconds * fps);
  const resolvedBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Create a mathematically perfect loop for horizontal scrolling
  const cycles = Math.round(3 * Math.abs(scrollSpeedMultiplier));
  const totalScrollDistance = cycles * itemWidth * Math.sign(scrollSpeedMultiplier);
  const scrollOffset = (frame / durationInFrames) * totalScrollDistance;

  // Sweeping diagonal wave that loops seamlessly
  const waveMin = -2200;
  const waveMax = 2200;
  const waveCenter = interpolate(frame, [0, durationInFrames], [waveMin, waveMax]);

  // Subtle organic spotlight overlay movement that loops perfectly via trig functions
  const spotX = Math.sin((frame / durationInFrames) * Math.PI * 2) * 500;
  const spotY = Math.cos((frame / durationInFrames) * Math.PI * 2) * 250;

  // Generate grid rows and columns to cover rotated canvas safely
  const numRows = 32;
  const numCols = 16;
  const rows = Array.from({ length: numRows }, (_, i) => i - Math.floor(numRows / 2));
  const cols = Array.from({ length: numCols }, (_, i) => i - Math.floor(numCols / 2));
  const totalRowWidth = numCols * itemWidth;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: resolvedBgColor,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
        fontFamily: rubikFamily,
      }}
    >
      {/* Rotated & Skewed Grid Wrapper */}
      <div
        style={{
          width: width * 2.2,
          height: height * 2.2,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
          transform: `rotate(${rotationAngle}deg) skewX(${skewAngle}deg)`,
          transformOrigin: "center center",
          transition: "none",
        }}
      >
        {rows.map((r) => {
          const isEven = r % 2 === 0;
          const dir = isEven ? 1 : -1;
          const offset = scrollOffset * dir;
          const stagger = isEven ? 0 : itemWidth / 2;

          // Align the row's accent line glow with the diagonal sweeping wave
          const rowCenterY = r * rowHeight;
          const rowWaveX = waveCenter - rowCenterY * 0.5;
          const relativeX = rowWaveX + totalRowWidth / 2;

          return (
            <div
              key={r}
              style={{
                position: "relative",
                height: rowHeight,
                width: totalRowWidth,
                display: "flex",
                flexDirection: "row",
                alignItems: "center",
                justifyContent: "center",
                transition: "none",
              }}
            >
              {/* Glowing horizontal laser line behind the text */}
              <div
                style={{
                  position: "absolute",
                  bottom: 0,
                  left: 0,
                  width: "100%",
                  height: 2,
                  background: `linear-gradient(90deg, rgba(255,15,15,0) ${relativeX - 600}px, rgba(255,15,15,${0.2 * lineOpacity}) ${relativeX - 150}px, rgba(255,15,15,${1.0 * lineOpacity}) ${relativeX}px, rgba(255,15,15,${0.2 * lineOpacity}) ${relativeX + 150}px, rgba(255,15,15,0) ${relativeX + 600}px)`,
                  transition: "none",
                }}
              />

              {/* Text elements */}
              {cols.map((c) => {
                const posX = c * itemWidth + offset + stagger;
                const posY = r * rowHeight;

                // Intensity from diagonal sweep wave
                const itemVal = posX * 0.8 + posY * 0.4;
                const distToWave = Math.abs(itemVal - waveCenter);
                const waveIntensity = Math.max(0, 1 - distToWave / waveWidth);

                // Intensity from subtle organic spotlight
                const distToSpot = Math.hypot(posX - spotX, posY - spotY);
                const spotIntensity = Math.max(0, 1 - distToSpot / 600) * 0.4;

                // Sum up glow factors
                const intensity = Math.min(1, Math.max(0, waveIntensity + spotIntensity));

                // Pure dynamic interpolations for coloring & sizing
                const color = interpolateColors(intensity, [0, 1], [dimTextColor, textColor]);
                const scale = 0.95 + intensity * 0.12;

                // Neon text-shadow layers for high contrast look
                const glowRadius = 15 * intensity * glowIntensity;
                const textShadow = intensity > 0.05
                  ? `0 0 ${glowRadius}px ${textColor}, 0 0 ${glowRadius * 2}px ${textColor}80`
                  : "none";

                return (
                  <div
                    key={c}
                    style={{
                      position: "absolute",
                      left: totalRowWidth / 2 + posX - itemWidth / 2,
                      width: itemWidth,
                      textAlign: "center",
                      color,
                      fontSize,
                      fontWeight: 900,
                      textShadow,
                      transform: `scale(${scale})`,
                      letterSpacing: "0.05em",
                      userSelect: "none",
                      transition: "none",
                    }}
                  >
                    SOS
                  </div>
                );
              })}
            </div>
          );
        })}
      </div>

      {/* Moody Vignette to tie the scene together */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: "radial-gradient(circle, rgba(0,0,0,0) 30%, rgba(0,0,0,0.85) 100%)",
          pointerEvents: "none",
          transition: "none",
        }}
      />
    </AbsoluteFill>
  );
};

export default SosBackground;